page Balls "/" {
  state count = 5
  state frames = 0
  state paused = false
  ref box
  ref balls
  ref raf
  ref pausedFlag
  ref frameCount

  fn rnd(a, b) {
    return a + Math.random() * (b - a)
  }

  fn makeBall() {
    return {
      x: rnd(10, 390),
      y: rnd(10, 290),
      vx: rnd(-3, 3),
      vy: rnd(-3, 3),
      r: 10
    }
  }

  fn resetBalls() {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push(makeBall())
    }
    frameCount = 0
    frames = 0
    count = 5
  }

  fn addBall() {
    balls.push(makeBall())
    count = balls.length
  }

  fn togglePause() {
    paused = !paused
    pausedFlag = paused
  }

  fn restart() {
    resetBalls()
    paused = false
    pausedFlag = false
  }

  fn step() {
    let W = 400
    let H = 300
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      if b.x < b.r {
        b.x = b.r
        b.vx = Math.abs(b.vx)
      }
      if b.x > W - b.r {
        b.x = W - b.r
        b.vx = -Math.abs(b.vx)
      }
      if b.y < b.r {
        b.y = b.r
        b.vy = Math.abs(b.vy)
      }
      if b.y > H - b.r {
        b.y = H - b.r
        b.vy = -Math.abs(b.vy)
      }
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let c = balls[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let d = Math.sqrt(dx * dx + dy * dy)
        let min = a.r + c.r
        if d < min {
          let nx = 1
          let ny = 0
          if d > 0 {
            nx = dx / d
            ny = dy / d
          }
          let overlap = (min - d) / 2
          a.x -= nx * overlap
          a.y -= ny * overlap
          c.x += nx * overlap
          c.y += ny * overlap
          let tvx = a.vx
          let tvy = a.vy
          a.vx = c.vx
          a.vy = c.vy
          c.vx = tvx
          c.vy = tvy
          a.x = Math.min(Math.max(a.x, a.r), W - a.r)
          a.y = Math.min(Math.max(a.y, a.r), H - a.r)
          c.x = Math.min(Math.max(c.x, c.r), W - c.r)
          c.y = Math.min(Math.max(c.y, c.r), H - c.r)
        }
      }
    }
  }

  fn draw() {
    let ctx = box.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#3b82f6"
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn loop() {
    if !pausedFlag {
      step()
      draw()
      frameCount = frameCount + 1
      frames = frameCount
    }
    raf = requestAnimationFrame(loop)
  }

  mount {
    pausedFlag = false
    frameCount = 0
    resetBalls()
    raf = requestAnimationFrame(loop)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    canvas ref=box id="sim" width=400 height=300 style="border:1px solid #888"
    row gap=2 {
      button "Agregar" -> addBall()
      button (paused ? "Reanudar" : "Pausar") -> togglePause()
      button "Reiniciar" -> restart()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

