import { useEffect, useRef, useState } from "react";

const W = 400;
const H = 300;
const R = 10;
const G = 0.2;

type Ball = { x: number; y: number; vx: number; vy: number };

const makeBall = (): Ball => ({
  x: R + Math.random() * (W - 2 * R),
  y: R + Math.random() * (H - 2 * R),
  vx: (Math.random() - 0.5) * 6 || 1,
  vy: (Math.random() - 0.5) * 6,
});

const makeBalls = (n: number): Ball[] => Array.from({ length: n }, makeBall);

function step(balls: Ball[]) {
  for (const b of balls) {
    b.vy += G;
    b.x += b.vx;
    b.y += b.vy;
    if (b.x < R) {
      b.x = R;
      b.vx = Math.abs(b.vx);
    } else if (b.x > W - R) {
      b.x = W - R;
      b.vx = -Math.abs(b.vx);
    }
    if (b.y < R) {
      b.y = R;
      b.vy = Math.abs(b.vy);
    } else if (b.y > H - R) {
      b.y = H - R;
      b.vy = -Math.abs(b.vy);
    }
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      let dx = b.x - a.x;
      let dy = b.y - a.y;
      let d = Math.hypot(dx, dy);
      if (d < 2 * R) {
        if (d === 0) {
          dx = 1;
          dy = 0;
          d = 1;
        }
        const nx = dx / d;
        const ny = dy / d;
        const overlap = 2 * R - d;
        a.x -= (nx * overlap) / 2;
        a.y -= (ny * overlap) / 2;
        b.x += (nx * overlap) / 2;
        b.y += (ny * overlap) / 2;
        // keep inside bounds after separation
        for (const p of [a, b]) {
          p.x = Math.min(W - R, Math.max(R, p.x));
          p.y = Math.min(H - R, Math.max(R, p.y));
        }
        // masas iguales: intercambian componente normal de la velocidad
        const van = a.vx * nx + a.vy * ny;
        const vbn = b.vx * nx + b.vy * ny;
        if (van - vbn > 0) {
          const diff = vbn - van;
          a.vx += diff * nx;
          a.vy += diff * ny;
          b.vx -= diff * nx;
          b.vy -= diff * ny;
        }
      }
    }
  }
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballsRef = useRef<Ball[]>(makeBalls(5));
  const framesRef = useRef(0);
  const [count, setCount] = useState(5);
  const [frames, setFrames] = useState(0);
  const [paused, setPaused] = useState(false);

  const draw = () => {
    const ctx = canvasRef.current?.getContext("2d");
    if (!ctx) return;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = "#0f172a";
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = "#38bdf8";
    for (const b of ballsRef.current) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
      ctx.fill();
    }
  };

  useEffect(() => {
    if (paused) {
      draw();
      return;
    }
    let id = 0;
    const loop = () => {
      step(ballsRef.current);
      draw();
      framesRef.current += 1;
      setFrames(framesRef.current);
      id = requestAnimationFrame(loop);
    };
    id = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(id);
  }, [paused]);

  const add = () => {
    ballsRef.current.push(makeBall());
    setCount(ballsRef.current.length);
    if (paused) draw();
  };

  const reset = () => {
    ballsRef.current = makeBalls(5);
    framesRef.current = 0;
    setCount(5);
    setFrames(0);
    draw();
  };

  const btn =
    "px-3 py-1 rounded bg-sky-600 text-white hover:bg-sky-700 active:bg-sky-800";

  return (
    <div className="min-h-screen flex flex-col items-center gap-3 p-4 bg-slate-100">
      <canvas
        id="sim"
        ref={canvasRef}
        width={W}
        height={H}
        className="border border-slate-400 rounded"
      />
      <div className="flex gap-2">
        <button className={btn} onClick={add}>
          Agregar
        </button>
        <button className={btn} onClick={() => setPaused((p) => !p)}>
          {paused ? "Reanudar" : "Pausar"}
        </button>
        <button className={btn} onClick={reset}>
          Reiniciar
        </button>
      </div>
      <div className="flex gap-4 text-slate-800">
        <span>Pelotas: {count}</span>
        <span>Cuadros: {frames}</span>
      </div>
    </div>
  );
}

