import { createSignal, onCleanup, onMount } from "solid-js";

interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  r: number;
  color: string;
}

const W = 400;
const H = 300;
const R = 10;
const G = 0.2;

const colors = ["#ef4444", "#3b82f6", "#22c55e", "#eab308", "#a855f7", "#f97316", "#14b8a6"];

function makeBall(): Ball {
  return {
    x: R + Math.random() * (W - 2 * R),
    y: R + Math.random() * (H - 2 * R),
    vx: (Math.random() * 2 - 1) * 4 || 1,
    vy: (Math.random() * 2 - 1) * 4,
    r: R,
    color: colors[Math.floor(Math.random() * colors.length)],
  };
}

function makeBalls(n: number): Ball[] {
  return Array.from({ length: n }, makeBall);
}

export default function App() {
  let canvas!: HTMLCanvasElement;
  let balls: Ball[] = makeBalls(5);
  let raf = 0;
  let paused = false;

  const [count, setCount] = createSignal(5);
  const [frames, setFrames] = createSignal(0);
  const [isPaused, setIsPaused] = createSignal(false);

  const draw = () => {
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = "#f8fafc";
    ctx.fillRect(0, 0, W, H);
    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
    }
  };

  const step = () => {
    for (const b of balls) {
      b.vy += G;
      b.x += b.vx;
      b.y += b.vy;
      if (b.x < b.r) {
        b.x = b.r;
        b.vx = Math.abs(b.vx);
      } else if (b.x > W - b.r) {
        b.x = W - b.r;
        b.vx = -Math.abs(b.vx);
      }
      if (b.y < b.r) {
        b.y = b.r;
        b.vy = Math.abs(b.vy);
      } else if (b.y > H - b.r) {
        b.y = H - b.r;
        b.vy = -Math.abs(b.vy);
      }
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i];
        const b = balls[j];
        let dx = b.x - a.x;
        let dy = b.y - a.y;
        let dist = Math.hypot(dx, dy);
        const min = a.r + b.r;
        if (dist < min) {
          if (dist === 0) {
            dx = 1;
            dy = 0;
            dist = 1;
          }
          const nx = dx / dist;
          const ny = dy / dist;
          // separar
          const overlap = (min - dist) / 2;
          a.x -= nx * overlap;
          b.x += nx * overlap;
          a.y -= ny * overlap;
          b.y += ny * overlap;
          // clamp a bordes
          for (const p of [a, b]) {
            p.x = Math.min(Math.max(p.x, p.r), W - p.r);
            p.y = Math.min(Math.max(p.y, p.r), H - p.r);
          }
          // intercambiar velocidades (solo si se acercan)
          const rvx = b.vx - a.vx;
          const rvy = b.vy - a.vy;
          if (rvx * nx + rvy * ny < 0) {
            const tvx = a.vx;
            const tvy = a.vy;
            a.vx = b.vx;
            a.vy = b.vy;
            b.vx = tvx;
            b.vy = tvy;
          }
        }
      }
    }
  };

  const loop = () => {
    if (paused) return;
    step();
    draw();
    setFrames((f) => f + 1);
    raf = requestAnimationFrame(loop);
  };

  const start = () => {
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(loop);
  };

  onMount(() => {
    draw();
    start();
  });

  onCleanup(() => cancelAnimationFrame(raf));

  const add = () => {
    balls.push(makeBall());
    setCount(balls.length);
    if (paused) draw();
  };

  const togglePause = () => {
    paused = !paused;
    setIsPaused(paused);
    if (!paused) start();
    else cancelAnimationFrame(raf);
  };

  const reset = () => {
    balls = makeBalls(5);
    setCount(5);
    setFrames(0);
    if (paused) draw();
  };

  const btn = "px-3 py-1 rounded bg-blue-600 text-white hover:bg-blue-700";

  return (
    <div class="p-4 flex flex-col items-center gap-3">
      <canvas
        id="sim"
        ref={canvas}
        width={400}
        height={300}
        class="border border-slate-400"
      />
      <div class="flex gap-2">
        <button class={btn} onClick={add}>Agregar</button>
        <button class={btn} onClick={togglePause}>
          {isPaused() ? "Reanudar" : "Pausar"}
        </button>
        <button class={btn} onClick={reset}>Reiniciar</button>
      </div>
      <div class="flex gap-4">
        <span>Pelotas: {count()}</span>
        <span>Cuadros: {frames()}</span>
      </div>
    </div>
  );
}

import { createSignal, onCleanup, onMount } from "solid-js";

interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  r: number;
}

const W = 400;
const H = 300;
const R = 10;
const G = 0.2;

function randomBall(): Ball {
  const angle = Math.random() * Math.PI * 2;
  const speed = 1 + Math.random() * 3;
  return {
    x: R + Math.random() * (W - 2 * R),
    y: R + Math.random() * (H - 2 * R),
    vx: Math.cos(angle) * speed,
    vy: Math.sin(angle) * speed,
    r: R,
  };
}

function createBalls(n: number): Ball[] {
  const arr: Ball[] = [];
  for (let i = 0; i < n; i++) arr.push(randomBall());
  return arr;
}

export default function App() {
  let canvas!: HTMLCanvasElement;
  let balls: Ball[] = createBalls(5);
  let raf = 0;
  let paused = false;
  let frames = 0;

  const [count, setCount] = createSignal(5);
  const [frameCount, setFrameCount] = createSignal(0);
  const [isPaused, setIsPaused] = createSignal(false);

  const draw = () => {
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = "#111827";
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = "#38bdf8";
    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fill();
    }
  };

  const step = () => {
    for (const b of balls) {
      b.vy += G;
      b.x += b.vx;
      b.y += b.vy;
      if (b.x < b.r) {
        b.x = b.r;
        b.vx = Math.abs(b.vx);
      } else if (b.x > W - b.r) {
        b.x = W - b.r;
        b.vx = -Math.abs(b.vx);
      }
      if (b.y < b.r) {
        b.y = b.r;
        b.vy = Math.abs(b.vy);
      } else if (b.y > H - b.r) {
        b.y = H - b.r;
        b.vy = -Math.abs(b.vy);
      }
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i];
        const b = balls[j];
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const minD = a.r + b.r;
        const d2 = dx * dx + dy * dy;
        if (d2 <= minD * minD) {
          let d = Math.sqrt(d2);
          let nx: number, ny: number;
          if (d === 0) {
            nx = 1;
            ny = 0;
            d = 0;
          } else {
            nx = dx / d;
            ny = dy / d;
          }
          // separar
          const overlap = (minD - d) / 2;
          a.x -= nx * overlap;
          a.y -= ny * overlap;
          b.x += nx * overlap;
          b.y += ny * overlap;
          // clamp a bordes
          for (const p of [a, b]) {
            p.x = Math.min(Math.max(p.x, p.r), W - p.r);
            p.y = Math.min(Math.max(p.y, p.r), H - p.r);
          }
          // intercambio de velocidades (masas iguales) en la normal
          const va = a.vx * nx + a.vy * ny;
          const vb = b.vx * nx + b.vy * ny;
          if (va - vb > 0) {
            const diff = vb - va;
            a.vx += diff * nx;
            a.vy += diff * ny;
            b.vx -= diff * nx;
            b.vy -= diff * ny;
          }
        }
      }
    }
  };

  const loop = () => {
    if (paused) return;
    step();
    draw();
    frames++;
    setFrameCount(frames);
    raf = requestAnimationFrame(loop);
  };

  const togglePause = () => {
    if (paused) {
      paused = false;
      setIsPaused(false);
      raf = requestAnimationFrame(loop);
    } else {
      paused = true;
      setIsPaused(true);
      cancelAnimationFrame(raf);
    }
  };

  const add = () => {
    balls.push(randomBall());
    setCount(balls.length);
    if (paused) draw();
  };

  const reset = () => {
    balls = createBalls(5);
    frames = 0;
    setCount(5);
    setFrameCount(0);
    draw();
  };

  onMount(() => {
    draw();
    raf = requestAnimationFrame(loop);
  });

  onCleanup(() => {
    paused = true;
    cancelAnimationFrame(raf);
  });

  return (
    <div class="min-h-screen bg-gray-900 text-white flex flex-col items-center gap-4 p-6">
      <canvas
        id="sim"
        ref={canvas}
        width={W}
        height={H}
        class="border border-gray-600 rounded"
      />
      <div class="flex gap-2">
        <button
          class="px-4 py-2 bg-sky-600 hover:bg-sky-500 rounded"
          onClick={add}
        >
          Agregar
        </button>
        <button
          class="px-4 py-2 bg-amber-600 hover:bg-amber-500 rounded"
          onClick={togglePause}
        >
          {isPaused() ? "Reanudar" : "Pausar"}
        </button>
        <button
          class="px-4 py-2 bg-rose-600 hover:bg-rose-500 rounded"
          onClick={reset}
        >
          Reiniciar
        </button>
      </div>
      <div class="flex gap-6 text-lg">
        <span>Pelotas: {count()}</span>
        <span>Cuadros: {frameCount()}</span>
      </div>
    </div>
  );
}
